insert into `slides` values ('3','轮播图3','内容3','/article/details?article=3','/api/upload/1627214265536479233.jpg','14','2023-03-11 09:56:38.0','2023-03-11 09:56:38.0');
insert into `article` values ('1','棋牌室到底归谁管？从文旅部这份公开答复说起','棋牌','640','0','2023-03-11 09:56:38.0','2023-03-11 09:56:38.0',null,null,null,'<p>就棋牌、麻将等业态是否属于《娱乐场所管理条例》和《娱乐场所管理办法》调整范围，笔者对文旅部答复有不同意见，认为棋牌、麻将等业态应属于《娱乐场所管理条例》调整范围，文化和旅游行政部门是棋牌室的行业主管部门。</p><p><br></p><p>棋牌室是否属于娱乐场所？</p><p><br></p><p>根据《娱乐场所管理条例》第二条和《娱乐场所管理办法》第二条的规定：娱乐场所是指以营利为目的，并向公众开放、消费者自娱自乐的歌舞、游艺等场所。歌舞娱乐场所是指提供伴奏音乐、歌曲点播服务或者提供舞蹈音乐、跳舞场地服务的经营场所；游艺娱乐场所是指通过游戏游艺设备提供游戏游艺服务的经营场所。据此，有部分文化执法人员认为棋牌室不属于上述法规、规章所规定的娱乐场所，即娱乐场所仅包含歌舞娱乐场所和游艺娱乐场所。这种看法是错误的，原因有三：</p><p><br></p><p>一是对棋牌室的监管符合《娱乐场所管理条例》立法目的。《娱乐场所管理条例》的制定是为了加强对娱乐场所的管理，保障娱乐场所的健康发展。棋牌室是向公众提供棋牌娱乐活动的专营或兼营的营利性场所，符合营利性、公众开放、自娱自乐等特征，显然是大众意义上的娱乐场所，对其按照娱乐场所监管符合《娱乐场所管理条例》立法目的。</p><p><br></p><p>二是《娱乐场所管理条例》相关规定符合对棋牌室监管的要求。根据《条例》可知，对娱乐场所的监管要求包含从业人员限制、开办场所限制、弘扬传统文化禁止内容限制、接纳招用未成年人限制等。上述规定与监管棋牌室要求一致。如认定棋牌室不属于《条例》监管内容，则需要针对棋牌室、桌游店等重新立法，进行法律规制，则造成重复立法，不符合法治政府要求。</p><p><br></p><p>三是《娱乐场所管理条例》中关于“歌舞、游艺等场所”规定应为“等外等”。在2020年9月最高检对全国人大《关于在法律法规、司法解释中进一步规范使用“等”字的建议》答复中明确提出，关于“等”字的使用，司法解释中一般有两种情形，一是表示列举后煞尾，即“等内等”；二是表示列举未尽，即“等外等”。最高人民检察院以往制定的司法解释中，“等”字多数是在第二种情况中使用，表示列举未尽。“等外等”的类比应该包括与明文列举范围相当或者甚于列举范围的情形，法律中要根据具体情节确定。就《娱乐场所管理条例》第二条规定而言，前述已表明棋牌室具备《条例》所规定的娱乐场所的各项特征，其与歌舞娱乐场所、游艺娱乐场所属于同范畴，此处“等”应为法律意义上的“等外等”。</p><p><br></p><p>棋牌室是否包含文化内容？</p><p><br></p><p>文旅部答复中称：“文化和旅游行政部门根据以上规定，对娱乐场所提供的文化内容和服务进行监管。棋牌、麻将等业态不含文化内容，不属于《娱乐场所管理条例》的调整范畴。”笔者认为该理解有误，原因有二：</p><p><br></p><p>一是棋牌、麻将、桌游和剧本杀等类型业态天然包含文化内容。以麻将为例，麻将牌是千百年来由多种棋牌活动融合、演变而成的，具有鲜明的中华传统文化的特点和意境，在境外麻将已成为中华文化的标志之一。同样桌游、剧本杀等新兴业态中也包含剧情故事等文化内容。在今年4月份，文化和旅游部等五部门联合起草了《关于规范剧本娱乐经营活动的通知（征求意见稿）》，意见稿中明确剧本杀经营属于《娱乐场所经营条例》调整范畴，实行备案管理。剧本杀作为棋牌的一种延伸新兴业态包含文化内容，而认为棋牌、麻将不含文化内容，显然有违逻辑和客观实际。因此，棋牌（含麻将、桌游）等，天然具有文化属性，包含文化内容。</p><p><br></p><p>二是根据线上线下一致性原则，棋牌娱乐具备文化属性。根据文化和旅游部规定，互联网上棋牌类游戏（无论是手游还是网页版），均需要在文化和旅游行政部门办理《网络文化经营许可证》，无网络文化经营许可证不得擅自开展互联网棋牌类游戏经营业务。在网络棋牌游戏属于文化经营前提下，棋牌室、麻将室不含文化内容显然不符合一致性原则。</p><p><br></p><p>为何台球、保龄球项目不属于娱乐项目？</p><p><br></p><p>在苏州市文化市场综合执法支队大队长钱骏撰写的《浅析棋牌室的监管职责争议》一文中，为证明棋牌娱乐中的“娱乐”并非法律语境中的语境（即证明棋牌室不是《条例》中的娱乐场所），类比了台球、保龄球项目。</p><p>在国务院法制办公室对《福建省人民政府法制办公室关于＜娱乐场所管理条例＞调整范围的请示》的复函中称：“《娱乐场所管理条例》第二条规定：‘本条例所称娱乐场所，是指向公众开放的、消费者自娱自乐的营业性歌舞、游艺等场所。’根据立法过程中协调达成的一致意见，并曾报经国务院领导审批同意，上述规定的适应范围不包括台球、保龄球等项目。”</p><p>台球、保龄球等项目经营场所提供教练、陪练服务，通过身体技能完成动作并达到娱乐和运动目的，属于体育运动项目。目前有关棋牌、竞技麻将等均成立了相关协会，作为群众体育运动推广，据此确易产生争议。面临同样问题的还有舞蹈和体育舞蹈应属于文旅部门主管还是体育部门主管问题。笔者认为，目前广泛存在的大众棋牌室、麻将馆，以及文化属性明显的剧本杀、桌游等，其面向群体为自娱自乐的群众，以娱乐游戏为主要目的，且不需要涉及身体健康与安全的专项体育运动指导，其应认定为娱乐场所，行业主管部门应为文化和旅游行政部门。</p><p>&nbsp;</p><p><br></p><p>棋牌馆该谁管？</p><p><br></p><p>有关棋牌馆由谁管的问题由来已久，因棋牌馆最为突出的噪音扰民问题，多年来多地媒体均有报道，“九龙治水”“踢皮球”问题也让百姓怨声载道。为此，部分地方对棋牌室的管理进行了专项规定，如《上海市营业性棋牌室管理暂行规定》《铜陵市营业性棋牌室管理暂行办法》等。在上述地方性立法中并未能对棋牌室是否属于《娱乐场所管理条例》管辖范畴进行统一，而是采取了“齐抓共管”的方式进行监管。</p><p><br></p><p>为何文化和旅游行政部门不愿承担行业主管部门的监管责任？分析其原因有三：</p><p><br></p><p>一是将棋牌室按照《娱乐场所管理条例》进行监管，则需要文化主管部门进行行政审批（备案）。《娱乐场所管理条例》第九条第一款规定：“娱乐场所申请从事娱乐场所经营活动，应当向所在地县级人民政府文化主管部门提出申请”。由于棋牌室申请量大，且多数棋牌室并不符合消防等规范要求，受理行政审批容易激发矛盾。</p><p><br></p><p>二是文化和旅游行政部门执法人员不足，多数有关棋牌室的投诉举报均涉及无证照经营、涉赌、噪音扰民等问题，处理难度较大。涉赌问题由公安部门管辖，噪音扰民问题由环保部门管辖，处理相关问题难度尚可。主要矛盾点在于无证照经营问题，由于执法力量不足，如文化和旅游部门根据法律法规接受其为行业主管部门，咱需要消耗大量行政力量处理无证照经营问题。</p><p><br></p><p>三是文化和旅游行政部门缺少强制措施。在查询相关媒体报道中笔者发现，大量文化执法人员在接受采访时提到因为缺少强制措施，对于违法违规棋牌室，在未涉刑或违反治安管理处罚条例时没有强制手段处理。关于缺少强制手段问题，目前已经解决。在2022年5月13日发布并实施的《文化和旅游部关于修改〈娱乐场所管理办法〉的决定》中，相关法条进行了修改，将第二十八条修改为“违反《条例》规定，擅自从事娱乐场所经营活动的，由县级以上人民政府文化和旅游主管部门依照《条例》第四十一条采取责令关闭等方式予以取缔，有违法所得的，依照《中华人民共和国行政处罚法》第二十八条予以没收；符合严重失信主体情形的，依照有关规定予以认定并实施相应信用管理措施”。</p><p><br></p><p>棋牌馆怎么管？</p><p><br></p><p>尽管5月13日实施的《文化和旅游部关于修改〈娱乐场所管理办法〉的决定》解决了对棋牌馆监管时缺乏强制手段的问题，但文化和旅游行政部门仍面临执法力量不足监管难度大等问题。因此，为解决棋牌室监管问题，提出以下两个建议：</p><p><br></p><p>一是明确棋牌馆、桌游店行政备案流程，摸清底数。针对棋牌馆、桌游店等娱乐场所，结合历史沿袭和客观实际，不适宜采用行政审批方式卡入口。可以参照对剧本娱乐场所监管征求意见中的方式，采取备案制，在文化和旅游行政部门进行备案，从而摸清底数，为下一步行业监管和合规做准备。以北京为例，目前全市棋牌馆等场所均暂停营业，应有效利用该时间窗口，将备案作为棋牌馆、桌游店等娱乐场所复工复产的前提条件，从而掌握当前棋牌馆等娱乐场所现状。</p><p><br></p><p>二是建立联席会商机制，行业主管部门牵头，各司其职，齐抓共管。文化和旅游行政主管部门作为行业主管部门，联合公安、市场监管、城管执法、消防救援、生态环境，体育等六部门（此处“等”后具体数字情形为“等内等”），建立联席会商制度，制定《联席会议制度》，明确各部门具体分工，落实对棋牌馆等娱乐场所的监管职责。如反映较大的扰民、涉赌类投诉举报，应直接派由环保和公安部门处置。</p><p><br></p><p>三是针对棋牌馆无证照等突出问题，由行业主管部门制定常态化方案，属地牵头，开展专项行动。要进一步强化属地责任，对于棋牌馆无证照等突出问题，由文化和旅游行政部门制定常态化方案，由属地牵头开展专项行动（以北京为例，可充分发挥“街乡吹哨，部门报到”机制优势），从而提升综合监管效率和治理效果。对于不易解决的无照经营点位，联合市场监管部门，用好《无证无照经营查处办法》第十四条的规定，对房屋产权人进行处罚，从而从物理空间上根本解决无证照棋牌馆问题。</p>','/api/upload/1627215938434629633.jpg',null);
insert into `article` values ('2','自助棋牌室开店解决方案','棋牌','466','0','2023-03-11 09:56:38.0','2023-03-11 09:56:38.0',null,null,null,'<p>开自助棋牌室，如何选址、如何装修规划、如何实现无人自助、如何预订使用、别人又是怎么做的？诸如此类问题，咨询者众多，今天小逸用文字+图片+视频的形式带你了解清楚，助力各位早日开启自己的“甩手掌柜”时代。</p><p><br></p><p><br></p><p>逸间云</p><p>COMPANY CULTURE</p><p>&nbsp;PART 01&nbsp;</p><p><br></p><p>自助棋牌室选址不受限制，根据周边人群需求、覆盖群体数量确认营业面积，例如写字楼开商务型的棋牌室，满足商务洽谈、品茗、娱乐的需求；在社区开娱乐型棋牌室，满足聚会、娱乐需求等。</p><p><br></p><p>示例1</p><p>写字楼内开自助棋牌室</p><p>多与茶室一同出现，满足商务品茗、棋牌娱乐的需求。</p><p><br></p><p>示例2</p><p>社区开自助棋牌室</p><p>满足周边居民休闲、娱乐的需求。</p><p><br></p><p>COMPANY CULTURE</p><p>&nbsp;PART 02</p><p><br></p><p>装修规划&nbsp;&nbsp;</p><p>逸间云为商家提供各种自助棋牌室装修规划和功能布局参考案例，比如：Ins风、国潮风、简约风、典雅风等。</p><p>（具体装修风格，可根据往日文章进行参考）</p><p><br></p><p>&nbsp;PART 03&nbsp;</p><p>无人自助化原理&nbsp;</p><p><br></p><p>01门禁原理</p><p>在门处安装电吸锁（或智能锁）、智能开关硬件，对接系统后可实现在小程序内自助开门</p><p><br></p><p>02电控原理</p><p>智能双键开关连接照明线、墙插线，并且安装在配电箱内，信号发射器负责将信号传输系统，从而实现系统控制座位通断电</p>','/api/upload/1627217547025711105.jpg',null);
insert into `article` values ('3','共享棋牌室经营数据天花板可以做到什么样','棋牌','555','0','2023-03-11 09:56:38.0','2023-03-11 09:56:38.0',null,null,null,'<p>· 共/享/棋/牌/室 ·</p><p><br></p><p><br></p><p><br></p><p>無老板：共享棋牌室经营数据天花板可以做到什么样？</p><p><br></p><p>棋牌室作为娱乐项目之一，本身的盈利空间很大。而共享棋牌室的出现又降低了棋牌室开店成本，实现低成本、高营收。那共享棋牌室经营数据天花板可以做到什么样呢？这里用一个無老板合作商家的真实案例做分析。</p><p><br></p><p>为什么说这家棋牌室是经营数据的天花板呢？</p><p><br></p><p><br></p><p><br></p><p>一、经营数据</p><p>这家棋牌室共2层，15个包间，2022年年收入接近60w元。计算下来：</p><p>月均营收：600000/12=50000元</p><p><br></p><p>日营收：50000/30=1666元</p><p><br></p><p>日均单房营收：1666/15=111元</p><p><img src="data:image/png;base64,"></p><p><br></p><p><br></p><p>与無老板合作的棋牌室商家，普遍月均做到2w-3w，这样对比下来，这位商家的棋牌室经营数据可谓是天花板。</p><p><br></p><p><br></p><p>而且今年该商户开了一家新的分店，共15个包间，仅仅营业10天就已经做到了2w的业绩，日均收入可达1818元，日均单房营收121元。这个成绩，已经超过了一部分棋牌室商家的月收入。</p><p><img src="data:image/png;base64,"></p><p><br></p><p>二、包间日均消费时长</p><p><br></p><p>自营业以来，棋牌室每个包间的日均消费时长在4-8小时。那商家可以结合日均消费时长，总结出哪些包间受欢迎，哪些包间使用频次较少。然后进行优化，或者结合卡券、优惠券做活动。</p><p><br></p><p>为什么这家棋牌室的日均消费时长数据较好呢？</p><p>首先，他位于四线城市，城市生活节奏较慢，人们也有时间去休闲娱乐。无所事事，约上三五好友，一起搓麻。打上头了，一坐就是一整晚。据后台数据也可以看出，预约订单大多都是通宵订单，一约就是四个小时、八个小时。</p><p><br></p><p>其次，24小时自助营业，模式够新颖，在四线城市也能吸引一波想尝试的人。而且24小时营业，顾客想什么时候来就什么时候来，不限制娱乐的时间。像现在很多年轻人是“夜猫子”，很多社交活动都是安排在晚上。</p><p><br></p><p>最后，该商家在服务上也很用心。每个包间都有独特的装修风格，国潮风、港风、小清新等等。在老店的基础上，开分店时还增加了儿童房，提供了贴心的服务。正因如此，才能提高客户粘性，发展忠实客户。</p><p><br></p><p>三、城镇租金便宜</p><p><br></p><p>在月均营收5w的情况下，城镇租金又相对便宜，大概在1w左右，棋牌室利润空间更大。</p><p><br></p><p>除此之外，该家棋牌室能做到经营天花板，也靠商家的门店经营能力。在开业初期懂得做活动促销，活动的优惠力度也是很吸引人。比如分店刚开业，做了引流活动，充值200赠200，充值500赠500。在原有用户的基础上，近30日为新老门店带来了300左右的新用户，平均一天就有10名新用户。</p><p><br></p><p>三四线城市租金一般都比较便宜，生活节奏慢，消费群体基数大。再稍加运营，就能达到不错的营收效果。这也是为什么棋牌室市场下沉三四线城市的原因，更加有盈利的空间。</p><p><br></p><p>本期就分享到这啦，出于保护商家的隐私，不公开部分数据。大多数和無老板合作的商家经营数据都不错，我们也希望商家生意兴隆，财源广进。</p><p><br></p>','/api/upload/1627218873545654273.jpg',null);
insert into `article` values ('4','生意越来越难做，棋牌室如何逆风翻盘？？？','棋牌','361','0','2023-03-11 09:56:38.0','2023-03-11 09:56:38.0',null,null,null,'<p>为什么选择</p><p><br></p><p>开自助棋牌室</p><p><br></p><p>24h营业/一键在线预约</p><p><br></p><p><img src="data:image/png;base64,"></p><p>低人工成本，</p><p><br></p><p>24小时无人值守模式；</p><p><br></p><p>无需经验，</p><p><br></p><p>自助化服务；</p><p><br></p><p>无需懂技术。</p><p><br></p><p>01智能自助棋牌室</p><p><br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;现在入行做棋牌室的老板一般都会推荐朋友选择智能自助模式来发展门店。像一些开始在线上引流的棋牌室老板，也都会在别人询问自己开店会不会很辛苦的时候，主动安利自助棋牌室的模式管理很轻松。</p><p><br></p><p>智能自助棋牌室行业，</p><p><br></p><p>在目前仍处于初级发展阶段；</p><p><br></p><p>社会认知度并不高，</p><p><br></p><p>不少地区还没普及全面。</p><p><br></p><p>但大众对这个模式还是充满新奇感，</p><p><br></p><p>要是你正好想开棋牌室，</p><p><br></p><p>不妨试试这种模式。</p><p><br></p><p><br></p><p>02优势在哪里</p><p><br></p><p>投入不大，</p><p><br></p><p>三四个包间就能开业；</p><p><br></p><p>节省80%以上的人力，</p><p><br></p><p>利用系统打造24小时自助模式，</p><p><br></p><p>顾客更轻松自在；</p><p><br></p><p>可复制性强，</p><p><br></p><p>方便开分店的老板更快地复制一家新门店</p><p><br></p><p><br></p><p>无人自助棋牌室，</p><p><br></p><p>有效的获客渠道有哪些？</p><p><br></p><p>建立线上客群，</p><p><br></p><p>奖励老带新客户，</p><p><br></p><p>线上平台宣传，</p><p><br></p><p>线下实体宣传；</p><p><br></p><p>美团店铺引流。</p>','/api/upload/1627215344139501569.jpg',null);
